-- Salvaguarda: si alguna fila no encontró su video_id (mapeo roto),
-- abortar la transacción entera en vez de dejar preguntas huérfanas.
DO $$
DECLARE huerfanas INT;
BEGIN
  SELECT COUNT(*) INTO huerfanas FROM public.preguntas WHERE video_id IS NULL;
  IF huerfanas > 0 THEN
    RAISE EXCEPTION 'Migración abortada: % preguntas sin video_id resuelto', huerfanas;
  END IF;
END $$;

COMMIT;

